            // uncommitted edits into conflict markers whenever a teammate had touched the same files,
            // and then handed that mess to the agent along with the user's message. Now the merge only
            // runs when it can't conflict; otherwise nothing is touched and the user is told.
            GitCommandResult fetch = RunGitDetailed(repoRoot, "fetch --quiet", GitSyncPullTimeoutMs);
            if (fetch == null)
                return TimedOutOutcome();
            if (fetch.ExitCode != 0)
